import { CommonModule } from '@angular/common';
import {
  Component,
  EventEmitter,
  HostListener,
  Input,
  Output,
} from '@angular/core';
import { ITabDropdownOption } from '../../interfaces';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';
import { OverlayPanelComponent } from '../overlay-panel/overlay-panel.component';

@Component({
  selector: 'custom-side-tabs',
  imports: [CommonModule, OverlayPanelComponent],
  templateUrl: './custom-side-tabs.component.html',
  styleUrl: './custom-side-tabs.component.css',
})
export class CustomSideTabsComponent {
  @Input() tabs: ITabDropdownOption[] = [];
  @Input() activeId!: string | number;
  @Input() lang: 'en' | 'ar' = 'en';

  @Output() activeIdChange = new EventEmitter<string | number>();

  isDesktop = window.innerWidth > 639;

  @HostListener('window:resize')
  onResize() {
    this.isDesktop = window.innerWidth > 639;
  }
  constructor(private sanitizer: DomSanitizer) {}

  getSafeSvg(svg: string | undefined): SafeHtml | null {
    if (!svg) return null;
    return this.sanitizer.bypassSecurityTrustHtml(svg);
  }

  selectTab(tab: ITabDropdownOption) {
    if (tab.disabled) return;

    this.activeId = tab.id;
    this.activeIdChange.emit(tab.id);
  }

  getLabel(tab: ITabDropdownOption): string {
    return this.lang === 'ar' ? tab.nameAr : tab.nameEn;
  }

  getTab(id: string | number): ITabDropdownOption {
    return this.tabs.filter((item) => item.id === id)[0];
  }
}
