import { TranslateModule } from '@ngx-translate/core';
import { Component, EventEmitter, input, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';

import { LoadingService } from '../../services';
import { trigger, transition, style, animate } from '@angular/animations';
// confirm.types.ts
export type ConfirmType = 'confirmation' | 'notifcation';
export type ConfirmResult = 'confirm' | 'cancel' | 'close';

export interface ConfirmOptions {
  modalText: string;
  modalSubText?: string;
  modalExtraText?: string;
  modalIcon: string;
  type: ConfirmType;
  confirmButtonText?: string;
  confirmButtonStyle?: string;
  cancelButtonText?: string;
  cancelButtonStyle?: string;
}

@Component({
  selector: 'custom-confirm-popup',
  imports: [CommonModule, TranslateModule],
  templateUrl: './custom-confirm-popup.component.html',
  styleUrl: './custom-confirm-popup.component.css',
  animations: [
    trigger('dialogAnim', [
      transition(':enter', [
        style({ transform: 'translateY(-20px)', opacity: 0 }),
        animate(
          '500ms ease-out',
          style({ transform: 'translateY(0)', opacity: 1 }),
        ),
      ]),
      transition(':leave', [
        animate(
          '200ms ease-in',
          style({ transform: 'translateY(-20px)', opacity: 0 }),
        ),
      ]),
    ]),
  ],
})
export class CustomConfirmPopupComponent {
  @Input({ required: true }) modalText: string = '';
  @Input({ required: true }) type: ConfirmType = 'confirmation';
  @Input() modalIcon: string = '';
  @Input() modalIconClass: string = '';
  @Input() modalSubText: string = '';
  @Input() modalExtraText: string = '';
  @Input() confirmButtonText: string = 'GENERAL.YES';
  @Input() confirmButtonStyle: string = 'vms-btn-danger';
  @Input() cancelButtonStyle: string = 'vms-btn-gray';
  @Input() cancelButtonText: string = 'GENERAL.NO';

  @Output() confirmEvent = new EventEmitter<any>();
  @Output() cancelEvent = new EventEmitter<void>();
  @Output() closeEvent = new EventEmitter<void>();
  @Output() overlayClicked = new EventEmitter<boolean>(false);

  successMsg = input<string>('');
  // Animation states
  successPressed = false;

  isVisible = false;
  eventVal: any;
  @Output() closed = new EventEmitter<void>();
  constructor(public loadingService: LoadingService) {}

  open(event?: any) {
    this.isVisible = true;
    this.eventVal = event;
  }

  close() {
    this.isVisible = false;
    this.closed.emit();
  }

  checkSuccess() {
    this.confirmEvent.emit();
    this.successPressed = true;
  }

  onOverlayClick(event: MouseEvent) {
    this.overlayClicked.emit(true);
    if (event.target === event.currentTarget) {
      this.isVisible = false;
      this.closed.emit();
    }
  }
}
