import { Component, EventEmitter, Input, Output } from '@angular/core';
import { FormGroup, ReactiveFormsModule } from '@angular/forms';
import { CustomAppErrorComponent } from '../custom-app-error/custom-app-error.component';
import { IComponentFormError } from '../../interfaces';
import { ComponentFormErrorConstant } from '../../enums';
import { NgClass, NgStyle } from '@angular/common';
import { consumerPollProducersForChange } from '@angular/core/primitives/signals';
import { CustomInputBase } from './custom-input-base';

@Component({
  selector: 'custom-input-form',
  standalone: true,
  imports: [NgStyle, ReactiveFormsModule, CustomAppErrorComponent, NgClass],
  templateUrl: './custom-input-form.component.html',
  styleUrls: ['./custom-input-form.component.css'],
})
export class CustomInputFormComponent extends CustomInputBase {
  @Input() numberType: 'currency' | 'time' | 'discount' | null = null;
  @Input() time: boolean = false;

  showPassword = false;

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
    if (this.showPassword) {
      this.type = 'text';
    } else {
      this.type = 'password';
    }
  }

  preventInvalidNumberInput(event: KeyboardEvent) {
    if (
      this.type === 'number' ||
      this.numberType === 'currency' ||
      this.numberType === 'time' ||
      this.numberType === 'discount'
    ) {
      const invalidKeys = ['-', '+', 'e', 'E'];
      if (invalidKeys.includes(event.key)) {
        event.preventDefault();
      }
    }
  }
}
