import {
  Component,
  EventEmitter,
  Input,
  Output,
  signal,
  inject,
  OnInit,
  OnDestroy,
  OnChanges,
  SimpleChange,
  SimpleChanges,
} from '@angular/core';
import { CustomAppErrorComponent } from '../custom-app-error/custom-app-error.component';
import { FormGroup, FormsModule, ReactiveFormsModule } from '@angular/forms';
import { IComponentFormError } from '../../interfaces';
import {
  ClickOutsideDirective,
  dropdownAnimation,
  DropdownsAnimationDirective,
} from '../../directives';
import { ComponentFormErrorConstant } from '../../enums';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { CustomTimeBaseComponent } from '../custom-time-input/custom-time-base';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'custom-time-input-form',
  imports: [
    CustomAppErrorComponent,
    ReactiveFormsModule,
    FormsModule,
    ClickOutsideDirective,
    TranslateModule,
    DropdownsAnimationDirective,
    CommonModule,
  ],
  templateUrl: './custom-time-input-form.component.html',
  styleUrl: './custom-time-input-form.component.css',
  animations: [dropdownAnimation],
})
export class CustomTimeInputFormComponent
  extends CustomTimeBaseComponent
  implements OnInit, OnDestroy, OnChanges
{
  @Input({ required: true }) parentForm!: FormGroup;
  @Input({ required: true }) name: string = '';
  @Input() controlName: string = '';
  @Input() label: string = '';
  @Input() labelClass: string = '';
  @Input() inputClass: string = '';
  @Input() validation: IComponentFormError[] = [];
  @Input() defaultTime: string = '';
  @Input() override rangeMin: string = '';
  @Input() override rangeMax: string = '';
  @Input() height: string = '3em';

  @Output() timeChange = new EventEmitter<{ hour: number; minute: number }>();

  private translate = inject(TranslateService);

  dropdownOpen = signal<boolean>(false);

  ngOnChanges(simple: SimpleChanges) {
    if (!this.parentForm) {
      return;
    }
    if (simple['rangeMax'] || simple['rangeMin']) {
      const control = this.parentForm.get(this.controlName);
      const currentValue = control?.value;
      if (currentValue && currentValue.length > 0) {
        // Re-parse so selectedHour/selectedPeriod are canonical 12h before
        // the range check runs.
        this.setExcistValue();
        if (!this.isTimeInRange()) {
          control?.setErrors({ timeRange: true });
          control?.markAsTouched();
          this.selectedHour = null;
          this.selectedMinute = null;
        }
      } else {
        this.selectedHour = null;
        this.selectedMinute = null;
      }
    }
  }

  ngOnInit() {
    if (this.defaultTime) {
      this.setTimeFromString(this.defaultTime);
    }
    const control = this.parentForm.get(this.controlName);
    if (control?.value) {
      this.setExcistValue();
    }
  }

  override ngAfterViewInit() {
    super.ngAfterViewInit();
  }

  ngOnDestroy() {
    // Clean up event listeners
  }

  containRequiredError() {
    return this.validation.some((error) =>
      error.errorType.includes(ComponentFormErrorConstant.REQUIRED),
    );
  }

  toggleDropdown() {
    this.dropdownOpen.set(!this.dropdownOpen());
    const control = this.parentForm.get(this.controlName);
    if (control?.value) {
      this.setExcistValue();
    }

    if (this.dropdownOpen()) {
      requestAnimationFrame(() => {
        this.updateItemHeight();
        this.scrollToSelectedValues();
      });
    }

    if (!this.dropdownOpen()) {
      this.parentForm.get(this.controlName)?.markAsTouched();
      this.confirmTime();
    }
  }

  confirmTime() {
    // Directly read scroll positions to ensure we have the latest values
    if (this.hourScrollRef) {
      const scrollTop = this.hourScrollRef.nativeElement.scrollTop;
      const index = Math.round(scrollTop / this.itemHeight);
      if (this.filteredHours[index] !== undefined) {
        this.selectedHour = this.filteredHours[index];
      }
    }

    if (this.minuteScrollRef) {
      const scrollTop = this.minuteScrollRef.nativeElement.scrollTop;
      const index = Math.round(scrollTop / this.itemHeight);
      if (this.filteredMinutes[index] !== undefined) {
        this.selectedMinute = this.filteredMinutes[index];
      }
    }

    if (this.periodScrollRef) {
      const scrollTop = this.periodScrollRef.nativeElement.scrollTop;
      const index = Math.round(scrollTop / this.itemHeight);
      if (this.filteredPeriods[index] !== undefined) {
        this.selectedPeriod = this.filteredPeriods[index] as 'AM' | 'PM';
      }
    }

    // Use == null so that 0 is NOT treated as missing (12 AM = 0 edge case).
    this.selectedHour =
      this.selectedHour == null || Number.isNaN(Number(this.selectedHour))
        ? this.filteredHours[0] || 9
        : this.selectedHour;
    this.selectedMinute =
      this.selectedMinute == null || Number.isNaN(Number(this.selectedMinute))
        ? this.filteredMinutes[0] || 0
        : this.selectedMinute;

    this.selectedPeriod =
      (this.selectedPeriod ?? this.filteredPeriods[0]) || 'AM';

    if (!this.isTimeInRange()) {
      this.parentForm.get(this.controlName)?.setErrors({ timeRange: true });
      this.parentForm.get(this.controlName)?.markAsTouched();
      this.selectedHour = this.filteredHours[0] || 8;
      this.selectedMinute = this.filteredMinutes[0] || 0;
      this.selectedPeriod = this.filteredPeriods[0] || 'AM';
      return;
    }

    // Convert to 24h only for writing to the form; keep internal state in 12h
    // so getters, displayTime, and re-opens stay consistent.
    const hour24 = this.to24Hour(
      Number(this.selectedHour),
      this.selectedPeriod,
    );
    this.setFormValue(hour24, Number(this.selectedMinute));
    this.dropdownOpen.set(false);
    this.timeChange.emit({
      hour: hour24,
      minute: Number(this.selectedMinute),
    });
  }

  setFormValue(hour24?: number, minute?: number) {
    if (hour24 === undefined || minute === undefined) {
      this.parentForm.get(this.controlName)?.setValue(null);
      return;
    }
    const targetHour = hour24 < 10 ? `0${hour24}` : `${hour24}`;
    const targetMin = minute < 10 ? `0${minute}` : `${minute}`;
    this.parentForm
      .get(this.controlName)
      ?.setValue(`${targetHour}:${targetMin}:00`);
  }

  setExcistValue() {
    const timeString = this.parentForm.get(this.controlName)?.value;
    if (!timeString) {
      return;
    }
    const [hourStr, minuteStr] = timeString.split(':');
    const hour = Number(hourStr);

    if (hour === 0) {
      this.selectedHour = 12;
      this.selectedPeriod = 'AM';
    } else if (hour === 12) {
      this.selectedHour = 12;
      this.selectedPeriod = 'PM';
    } else if (hour > 12) {
      this.selectedHour = hour - 12;
      this.selectedPeriod = 'PM';
    } else {
      this.selectedHour = hour;
      this.selectedPeriod = 'AM';
    }

    this.selectedMinute = Number(minuteStr);
  }

  displayTime(): string | null {
    const value = this.parentForm.get(this.controlName)?.value;
    const periodLabel = this.translate.instant(
      'GENERAL.' + (this.selectedPeriod || 'AM'),
    );

    if (value == null || value.length === 0) {
      return `--:-- ${periodLabel}`;
    }

    const hour =
      Number(this.selectedHour) > 12
        ? (Number(this.selectedHour) - 12).toString().padStart(2, '0')
        : this.selectedHour?.toString().padStart(2, '0') || '--';
    const minute = this.selectedMinute?.toString().padStart(2, '0') || '--';
    return `${hour}:${minute} ${periodLabel}`;
  }

  private isTimeInRange(): boolean {
    if (!this.rangeMin && !this.rangeMax) {
      return true;
    }

    // selectedHour may be in 12h format (post setExcistValue) or 24h format
    // (post confirmTime legacy behavior). Normalize to 24h before comparing
    // against rangeMin/rangeMax which are always 24h.
    const hour12 = Number(this.selectedHour);
    const hour24 =
      hour12 > 12 ? hour12 : this.to24Hour(hour12, this.selectedPeriod);

    const selectedTime = this.getTimeInHours(hour24, Number(this.selectedMinute));

    if (this.rangeMin) {
      const [minH, minM] = this.rangeMin.split(':').map(Number);
      const minTime = this.getTimeInHours(minH, minM);
      if (selectedTime < minTime) {
        return false;
      }
    }

    if (this.rangeMax) {
      const [maxH, maxM] = this.rangeMax.split(':').map(Number);
      const maxTime = this.getTimeInHours(maxH, maxM);
      if (selectedTime > maxTime) {
        return false;
      }
    }

    return true;
  }

  private getTimeInHours(hour: number, minute: number): number {
    return hour + minute / 60;
  }
}
