import {
  Component,
  EventEmitter,
  inject,
  Input,
  Output,
  signal,
  OnInit,
  OnChanges,
  SimpleChanges,
  ElementRef,
} from '@angular/core';
import { ClickOutsideDirective } from '../../directives';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { CustomTimeBaseComponent } from './custom-time-base';

@Component({
  selector: 'custom-time-input',
  imports: [TranslateModule, ClickOutsideDirective],
  templateUrl: './custom-time-input.component.html',
  styleUrl: './custom-time-input.component.css',
})
export class CustomTimeInputComponent
  extends CustomTimeBaseComponent
  implements OnInit, OnChanges
{
  @Input() value: string | null = null;
  @Output() valueChange = new EventEmitter<string | null>();

  @Input() label = '';
  @Input() labelClass = '';
  @Input() inputClass = '';
  @Input() height = '4.8em';
  @Input() override rangeMin = '';
  @Input() override rangeMax = '';
  @Input() required = false;
  @Input() defaultTime: string = '';

  private translate = inject(TranslateService);

  dropdownOpen = signal(false);

  ngOnInit(): void {
    if (this.defaultTime) {
      this.setTimeFromString(this.defaultTime);
    }
    if (this.value) {
      this.setFromValue(this.value);
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    // Skip the first cycle — ngOnInit handles the initial value.
    if (changes['value'] && !changes['value'].firstChange) {
      if (this.value) {
        this.setFromValue(this.value);
      } else {
        this.selectedHour = null;
        this.selectedMinute = null;
      }
    }

    if (
      (changes['rangeMin'] || changes['rangeMax']) &&
      this.value &&
      this.selectedHour != null &&
      this.selectedMinute != null
    ) {
      if (!this.isTimeInRange()) {
        this.selectedHour = null;
        this.selectedMinute = null;
        this.valueChange.emit(null);
      }
    }
  }

  override ngAfterViewInit() {
    super.ngAfterViewInit();
  }

  toggleDropdown(): void {
    this.dropdownOpen.set(!this.dropdownOpen());

    if (this.dropdownOpen()) {
      requestAnimationFrame(() => {
        this.updateItemHeight();
        this.scrollToSelectedValues();
      });
    }

    if (!this.dropdownOpen()) {
      if (!this.value) {
        // Set default to current time or 09:00 AM
        this.selectedHour = this.filteredHours[0] || 9;
        this.selectedMinute = this.filteredMinutes[0] || 0;
        this.selectedPeriod = this.filteredPeriods[0] || 'AM';
      }
      this.confirmTime();
    }
  }

  onHourChange(): void {
    const mins = this.filteredMinutes;

    if (mins.length === 1) {
      this.selectedMinute = mins[0];
    }

    if (this.selectedMinute != null && !mins.includes(this.selectedMinute)) {
      this.selectedMinute = undefined;
    }
  }

  confirmTime(): void {
    if (
      this.selectedHour == null ||
      this.selectedMinute == null ||
      !this.isTimeInRange()
    ) {
      this.valueChange.emit(null);
      return;
    }

    let hour24 = this.selectedHour;

    if (this.selectedPeriod === 'PM' && hour24 !== 12) {
      hour24 += 12;
    }
    if (this.selectedPeriod === 'AM' && hour24 === 12) {
      hour24 = 0;
    }

    const h = hour24.toString().padStart(2, '0');
    const m = this.selectedMinute.toString().padStart(2, '0');

    this.valueChange.emit(`${h}:${m}:00`);
    this.dropdownOpen.set(false);
  }

  displayTime(): string {
    if (this.selectedHour == null || this.selectedMinute == null) {
      return '--:--';
    }

    return `${
      this.selectedHour > 12
        ? this.selectedHour - 12
        : this.selectedHour.toString().padStart(2, '0')
    }:${this.selectedMinute
      .toString()
      .padStart(2, '0')} ${this.translate.instant(
      'GENERAL.' + this.selectedPeriod,
    )}`;
  }

  private setFromValue(value: string): void {
    const timeString = value.substring(0, 5); // "HH:MM"
    const [hourStr, minuteStr] = timeString.split(':');
    const hour = Number(hourStr);

    if (hour === 0) {
      this.selectedHour = 12;
      this.selectedPeriod = 'AM';
    } else if (hour === 12) {
      this.selectedHour = 12;
      this.selectedPeriod = 'PM';
    } else if (hour > 12) {
      this.selectedHour = hour - 12;
      this.selectedPeriod = 'PM';
    } else {
      this.selectedHour = hour;
      this.selectedPeriod = 'AM';
    }

    this.selectedMinute = Number(minuteStr);
  }

  private isTimeInRange(): boolean {
    if (!this.rangeMin && !this.rangeMax) return true;

    const hour24 = this.to24Hour(this.selectedHour!, this.selectedPeriod);

    const selected = hour24 * 60 + this.selectedMinute!;

    if (this.rangeMin) {
      const [h, m] = this.rangeMin.split(':').map(Number);
      if (selected < h * 60 + m) return false;
    }

    if (this.rangeMax) {
      const [h, m] = this.rangeMax.split(':').map(Number);
      if (selected > h * 60 + m) return false;
    }

    return true;
  }
}
