import {
  Component,
  EventEmitter,
  Input,
  Output,
  OnDestroy,
  OnInit,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Subject } from 'rxjs';
import { debounceTime } from 'rxjs/operators';

@Component({
  selector: 'custom-search-input',
  imports: [FormsModule],
  templateUrl: './custom-search-input.component.html',
  styleUrl: './custom-search-input.component.css',
})
export class CustomSearchInputComponent implements OnInit, OnDestroy {
  @Input() class: string = '';
  @Input() labelClass: string = '';
  @Input() label: string = '';
  @Input() placeholder: string = '';
  @Input() name: string = '';
  @Input({ required: true }) value: any;
  @Input() style: 'base' | 'white' | 'grey' = 'base'; // ps. these have effect on style and color
  @Input() height: string = '4.8rem';
  @Output() valueChange = new EventEmitter<any>();

  private searchSubject = new Subject<string>();

  ngOnInit() {
    this.searchSubject.pipe(debounceTime(300)).subscribe((value) => {
      const val = value?.trim() || '';
      if (!(val.length <= 0 && this.value?.length > 0)) {
        this.valueChange.emit(val);
      }
    });
  }

  ngOnDestroy() {
    this.searchSubject.complete();
  }

  emitSearch(value: string) {
    this.searchSubject.next(value);
  }
}
