import { Component, inject, Input } from '@angular/core';
import { TranslationService } from '../../services';
import { TranslateModule } from '@ngx-translate/core';
export interface AvatarItem {
  imgPath?: string;
  name: string;
  disabled?: boolean;
}

@Component({
  selector: 'custom-avatars',
  imports: [TranslateModule],
  templateUrl: './custom-avatars.component.html',
  styleUrl: './custom-avatars.component.css',
})
export class CustomAvatarsComponent {
  @Input() items: AvatarItem[] = [];
  @Input() size = 3; // size in em
  @Input() overlapOffset = 0.7;
  @Input() removeOutline = false;
  @Input() removeBorder = false;

  translationService = inject(TranslationService);

  getInitials(name: string): string {
    return name
      .split(' ')
      .map((part) => part.charAt(0).toUpperCase())
      .join('');
  }
  getRandomColor(name: string): string {
    const colors = [
      'var(--vms-red-light-active)',
      'var(--vms-yellow-light-active)',
      'var(--vms-green-light-active)',
      'var(--vms-blue-light-active)',
      'var(--vms-lavender-light-active)',
    ];
    let hash = 0;
    for (let i = 0; i < name.length; i++) {
      hash = name.charCodeAt(i) + ((hash << 5) - hash);
    }
    const index = Math.abs(hash) % colors.length;
    return colors[index];
  }
}
