import { inject, Injectable, signal } from '@angular/core';
import { StorageService } from '../auth/storage.services';

@Injectable({ providedIn: 'root' })
export class SidenavService {
  private _isCollapsed = signal<boolean>(false);
  private _hidden = signal<boolean>(false); // only for mobile view
  private _isMobileView = signal<boolean>(false);

  constructor() {
    // Initialize from sessionStorage on service creation
    const storedState = sessionStorage.getItem('isCollapsed');
    if (storedState === 'true') {
      this._isCollapsed.set(true);
    }
    this.listenToWindowResize();
  }

  get isCollapsed() {
    return this._isCollapsed();
  }
  get hidden() {
    return this._hidden();
  }

  get isMobileView() {
    return this._isMobileView();
  }

  toggle() {
    const newVal = !this._isCollapsed();
    sessionStorage.setItem('isCollapsed', newVal.toString());
    this._isCollapsed.set(newVal);
  }

  toggleHide() {
    if (this.isMobileView) {
      const newVal = !this._hidden();
      this._hidden.set(newVal);
    }
  }

  hide() {
    if (this.isMobileView) {
      this._hidden.set(true);
    }
  }

  collapse() {
    this._isCollapsed.set(true);
    sessionStorage.setItem('isCollapsed', 'true');
  }

  expand() {
    this._isCollapsed.set(false);
    sessionStorage.setItem('isCollapsed', 'false');
  }
  private listenToWindowResize() {
    const handleResize = () => {
      const width = window.innerWidth;

      // Always collapse when < 900px
      if (width < 640) {
        this._isCollapsed.set(false);
        this._hidden.set(true);
        this._isMobileView.set(true);
        sessionStorage.setItem('isCollapsed', 'false');
      } else if (width < 1025) {
        this._isCollapsed.set(true);
        this._hidden.set(false);
        this._isMobileView.set(false);
        sessionStorage.setItem('isCollapsed', 'true');
      }

      // Always expand when >= 700px
      else {
        this._isCollapsed.set(false);
        this._hidden.set(false);
        this._isMobileView.set(false);
        sessionStorage.setItem('isCollapsed', 'false');
      }
    };

    // Initial check
    handleResize();

    // Listen to resize
    window.addEventListener('resize', handleResize);
  }
}
