import { Component, Input } from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { CustomAppErrorComponent } from '../../custom-app-error/custom-app-error.component';
import { NgClass, NgStyle } from '@angular/common';
import { CustomInputBase } from '../custom-input-base';

@Component({
  selector: 'custom-plate-number-input',
  standalone: true,
  imports: [NgStyle, ReactiveFormsModule, CustomAppErrorComponent],
  templateUrl: './custom-plate-number-input.component.html',
  styleUrls: ['./custom-plate-number-input.component.css'],
})
export class CustomPlateNumberInputComponent extends CustomInputBase {
  @Input() maxLetters: number = 3;
  @Input() maxDigits: number = 4;
  @Input() placeholderLetters: string = 'ABC';
  @Input() placeholderDigits: string = '1234';

  lettersValue: string = '';
  digitsValue: string = '';

  override ngOnInit() {
    super.ngOnInit();

    // Initialize from existing form value if present
    const currentValue = this.parentForm.controls[this.controlName].value;
    if (currentValue) {
      this.splitPlateNumber(currentValue);
    }
    // console.log(
    //   'CustomPlateNumberInputComponent initialized with value:',
    //   currentValue,
    //   this.parentForm.controls[this.controlName].value,
    // );

    // Subscribe to form control value changes to handle external updates
    this.parentForm.controls[this.controlName].valueChanges.subscribe(
      (value) => {
        // console.log('Form control value changed:', value);
        if (value && value !== this.getCombinedValue()) {
          this.splitPlateNumber(value);
        }
      },
    );
  }

  preventInvalidInput(event: KeyboardEvent, type: 'letters' | 'digits') {
    if (type === 'letters') {
      // Allow English and Arabic letters and control keys
      if (
        !/[a-zA-Z\u0621-\u064A]/.test(event.key) &&
        !this.isControlKey(event)
      ) {
        event.preventDefault();
      }
    } else if (type === 'digits') {
      // Allow English and Arabic digits and control keys
      if (!/[0-9\u0660-\u0669]/.test(event.key) && !this.isControlKey(event)) {
        event.preventDefault();
      }
    }
  }

  isControlKey(event: KeyboardEvent): boolean {
    return (
      event.key === 'Backspace' ||
      event.key === 'Delete' ||
      event.key === 'Tab' ||
      event.key === 'Escape' ||
      event.key === 'Enter' ||
      event.key === 'ArrowLeft' ||
      event.key === 'ArrowRight' ||
      event.key === 'Home' ||
      event.key === 'End' ||
      (event.ctrlKey && event.key === 'a') ||
      (event.ctrlKey && event.key === 'c') ||
      (event.ctrlKey && event.key === 'v') ||
      (event.ctrlKey && event.key === 'x')
    );
  }

  updateFormValue() {
    const combinedValue = this.getCombinedValue();
    this.parentForm.controls[this.controlName].setValue(combinedValue);
    this.parentForm.controls[this.controlName].markAsTouched();
    this.valueChange.emit(combinedValue);
  }

  // Helper to add spaces between characters for display
  formatWithSpaces(value: string): string {
    return value.split('').join(' ');
  }

  splitPlateNumber(value: string) {
    if (!value) return;
    const parts = value.split(' ');
    if (parts.length === 2) {
      this.lettersValue = this.formatWithSpaces(parts[0] || '');
      this.digitsValue = this.formatWithSpaces(parts[1] || '');
    } else {
      this.lettersValue = this.formatWithSpaces(
        value.substring(0, this.maxLetters),
      );
      this.digitsValue = this.formatWithSpaces(
        value.substring(this.maxLetters, this.maxLetters + this.maxDigits),
      );
    }
  }

  onLettersInput(event: Event) {
    const input = event.target as HTMLInputElement;
    // Strip spaces to get raw value, then uppercase
    let raw = input.value.replace(/\s/g, '').toUpperCase();

    raw = raw.replace(/[^ABDGHJKLMNPRSTUVXZ\u0621-\u064A]/g, '');

    if (raw.length > this.maxLetters) {
      raw = raw.substring(0, this.maxLetters);
    }

    this.lettersValue = this.formatWithSpaces(raw);
    input.value = this.lettersValue;

    // console.log('[Letters] raw:', raw, '| display:', this.lettersValue);

    if (raw.length === this.maxLetters) {
      const digitsInput = input.nextElementSibling as HTMLInputElement;
      if (digitsInput) digitsInput.focus();
    }

    if (raw.length < this.maxLetters) {
      this.parentForm.controls[this.controlName].setErrors({ minlength: true });
    } else {
      this.parentForm.controls[this.controlName].setErrors(null);
    }

    this.updateFormValue();
  }

  onDigitsInput(event: Event) {
    const input = event.target as HTMLInputElement;
    // Strip spaces to get raw value
    let raw = input.value.replace(/\s/g, '');

    raw = raw.replace(/[^0-9\u0660-\u0669]/g, '');

    if (raw.length > this.maxDigits) {
      raw = raw.substring(0, this.maxDigits);
    }

    this.digitsValue = this.formatWithSpaces(raw);
    input.value = this.digitsValue;

    // console.log('[Digits] raw:', raw, '| display:', this.digitsValue);

    if (raw.length < this.maxDigits) {
      this.parentForm.controls[this.controlName].setErrors({ minlength: true });
    } else {
      this.parentForm.controls[this.controlName].setErrors(null);
    }

    this.updateFormValue();
  }

  getCombinedValue(): string {
    if (!this.lettersValue && !this.digitsValue) return '';
    // Strip display spaces before storing
    const rawLetters = this.lettersValue.replace(/\s/g, '');
    const rawDigits = this.digitsValue.replace(/\s/g, '');
    const combined = `${rawLetters} ${rawDigits}`.trim();
    // console.log('[Combined] stored value:', combined);
    return combined;
  }
}
