import { CommonModule } from '@angular/common';
import {
  Component,
  EventEmitter,
  inject,
  Input,
  Output,
  TemplateRef,
  ViewChild,
  ElementRef,
  OnDestroy,
} from '@angular/core';
import { ITabDropdownOption } from '../../interfaces';
import { TranslationService } from '../../services';
import { LocalizePipe } from '../../pipes';
import { OverlayPanelComponent } from '../overlay-panel/overlay-panel.component';

@Component({
  selector: 'custom-pill-tabs',
  imports: [CommonModule, LocalizePipe, OverlayPanelComponent],
  templateUrl: './custom-pill-tabs.component.html',
  styleUrl: './custom-pill-tabs.component.css',
})
export class CustomPillTabsComponent implements OnDestroy {
  @Input({ required: true }) tabsList!: ITabDropdownOption[];
  @Input() color: string = '#120710'; // text color when not selected
  @Input() colorSelected: string = '#120710'; // text color when selected
  @Input() backgroundColor: string = '#F5F5F5'; // background color of the pill tabs
  @Input() backgroundColorSelected: string = '#FFFFFF'; // background color when selected
  @Input() tabTemplates: { [key: string]: TemplateRef<any> } = {};
  @Input() selectedTab!: ITabDropdownOption;
  @Input() tabClass: string = '';
  @Output() tabSelected: EventEmitter<ITabDropdownOption> =
    new EventEmitter<ITabDropdownOption>();

  @ViewChild('tabContainer') tabContainer!: ElementRef<HTMLDivElement>;

  translationService = inject(TranslationService);
  private dirObserver: MutationObserver | undefined;

  ngOnInit() {
    if (!this.selectedTab) this.selectedTab = this.tabsList[0];
  }

  ngAfterViewInit() {
    this.updatePillPosition();

    this.dirObserver = new MutationObserver(() => {
      this.updatePillPosition();
    });
    this.dirObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['dir'],
    });
  }

  ngOnDestroy() {
    this.dirObserver?.disconnect();
  }

  selectTab(tab: ITabDropdownOption) {
    this.selectedTab = tab;
    this.tabSelected.emit(tab);
    setTimeout(() => this.updatePillPosition(), 0);
  }

  private updatePillPosition() {
    if (!this.tabContainer) return;

    const buttons =
      this.tabContainer.nativeElement.querySelectorAll('.tab-button');
    const selectedIndex = this.tabsList.findIndex(
      (tab) => tab.id === this.selectedTab.id,
    );

    if (selectedIndex !== -1 && buttons[selectedIndex]) {
      const button = buttons[selectedIndex] as HTMLElement;
      const containerRect =
        this.tabContainer.nativeElement.getBoundingClientRect();
      const buttonRect = button.getBoundingClientRect();

      const translateX = buttonRect.left - containerRect.left - 0.4;
      const pillWidth = buttonRect.width;

      const container = this.tabContainer.nativeElement;
      container.style.setProperty('--pill-translate', `${translateX}px`);
      container.style.setProperty('--pill-width', `${pillWidth}px`);
    }
  }
}
