import {
  Component,
  EventEmitter,
  Input,
  Output,
  SimpleChanges,
} from '@angular/core';
import { ReactiveFormsModule } from '@angular/forms';
import { CustomAppErrorComponent } from '../../custom-app-error/custom-app-error.component';
import { NgStyle } from '@angular/common';
import { CustomInputBase } from '../custom-input-base';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'custom-input-number-form',
  standalone: true,
  imports: [TranslateModule, ReactiveFormsModule, CustomAppErrorComponent],
  templateUrl: './custom-input-number-form.component.html',
  styleUrls: ['./custom-input-number-form.component.scss'],
})
export class CustomInputNumberFormComponent extends CustomInputBase {
  @Input({ required: true }) numberType:
    | 'outerIncrements'
    | 'number'
    | 'outerIncBlue'
    | null = null;
  @Input() min: number = 0;
  @Input() max: number = Infinity;
  @Input() typeName: string = '';
  @Input() fontSize: string = '2.4rem';
  @Input() width: string = '39.5em';
  @Output() numberValueChange: EventEmitter<number> =
    new EventEmitter<number>();

  override ngOnInit(): void {
    super.ngOnInit();
    if (this.type !== 'number') {
      throw new Error(
        `Invalid input type for CustomInputNumberFormComponent. Expected 'number', got '${this.type}'.`,
      );
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['disabled']) {
      if (this.disabled) {
        this.parentForm.controls[this.controlName].disable();
      } else {
        this.parentForm.controls[this.controlName].enable();
      }
    }
  }

  showPassword = false;

  togglePasswordVisibility(): void {
    this.showPassword = !this.showPassword;
    if (this.showPassword) {
      this.type = 'text';
    } else {
      this.type = 'password';
    }
  }

  preventInvalidNumberInput(event: KeyboardEvent): void {
    // Allow control keys
    const allowedKeys = [
      'Backspace',
      'Delete',
      'Tab',
      'Escape',
      'Enter',
      'ArrowLeft',
      'ArrowRight',
      'ArrowUp',
      'ArrowDown',
      'Home',
      'End',
    ];

    // Allow Ctrl/Cmd + A (Select All), C (Copy), V (Paste), X (Cut)
    if (event.ctrlKey || event.metaKey) {
      if (['a', 'c', 'v', 'x'].includes(event.key.toLowerCase())) {
        return;
      }
    }

    // Allow numbers (0-9) from both main keyboard and numpad
    const isNumber = /^[0-9]$/.test(event.key);

    // If it's not a number and not an allowed control key, prevent it
    if (!isNumber && !allowedKeys.includes(event.key)) {
      event.preventDefault();
      return;
    }

    // Check min/max constraints for number input
    if (isNumber) {
      const control = this.parentForm.controls[this.controlName];
      const currentValue = control.value || '';
      const newValue = Number(currentValue + event.key);

      if (newValue > this.max || newValue < this.min) {
        event.preventDefault();
      }
    }
  }

  incrementValue(): void {
    const control = this.parentForm.controls[this.controlName];
    const currentValue = Number(control.value) || 0;
    const step = 1;
    const newValue = currentValue + step;
    control.setValue(newValue);
    control.markAsTouched();
    this.numberValueChange.emit(newValue);
  }

  decrementValue(): void {
    const control = this.parentForm.controls[this.controlName];
    const currentValue = Number(control.value) || 0;
    const step = 1;
    const newValue = Math.max(this.min, currentValue - step);
    control.setValue(newValue);
    control.markAsTouched();
    this.numberValueChange.emit(newValue);
  }
}
